(function(root){'use strict';
const F=[['name','Nome'],['address','Endereço'],['phone','Telefone'],['birthDate','Nascimento'],['age','Idade informada'],['role','Função'],['cpf','CPF'],['rg','RG'],['admissionDate','Admissão'],['companyStatus','Vínculo'],['spreadsheetNote','Observações'],['category','Categoria'],['active','Ativo']];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const names=e=>String(e.name||'funcionario').normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9]+/gi,'-').toLowerCase();
const cell=(e,k)=>k==='active'?(e.active===false?'Não':'Sim'):k==='companyStatus'?({'engefex':'Engefex','outro_cnpj':'Outro CNPJ','afastado':'Afastado'}[e.companyStatus]||'Engefex'):String(e[k]??'');
const dl=(data,type,name)=>{const u=URL.createObjectURL(new Blob([data],{type})),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),4000)};
async function exportData(items,kind){const data=[F.map(x=>x[1]),...items.map(e=>F.map(([k])=>cell(e,k)))];const name=items.length===1?'funcionario-'+names(items[0]):'funcionarios-engefex';if(kind==='csv'){dl('\uFEFF'+data.map(r=>r.map(v=>'"'+String(v).replace(/"/g,'""')+'"').join(';')).join('\r\n'),'text/csv;charset=utf-8',name+'.csv');return;}
if(!root.JSZip)throw Error('Biblioteca Excel indisponível');const xml=s=>String(s??'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');const col=n=>String.fromCharCode(65+n);const sheet='<worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main"><sheetData>'+data.map((r,i)=>'<row r="'+(i+1)+'">'+r.map((v,j)=>'<c r="'+col(j)+(i+1)+'" t="inlineStr"><is><t>'+xml(v)+'</t></is></c>').join('')+'</row>').join('')+'</sheetData></worksheet>';
const z=new root.JSZip();z.file('[Content_Types].xml','<Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/><Override PartName="/xl/workbook.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml"/><Override PartName="/xl/worksheets/sheet1.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml"/></Types>');z.file('_rels/.rels','<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="r1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="xl/workbook.xml"/></Relationships>');z.file('xl/workbook.xml','<workbook xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships"><sheets><sheet name="Funcionários" sheetId="1" r:id="r1"/></sheets></workbook>');z.file('xl/_rels/workbook.xml.rels','<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="r1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet" Target="worksheets/sheet1.xml"/></Relationships>');z.file('xl/worksheets/sheet1.xml',sheet);dl(await z.generateAsync({type:'blob'}),'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',name+'.xlsx');}
function attach(s,persist,render,notify){if(!document.getElementById('hrSpreadsheet'))return;const panel=document.querySelector('#hrNew')?.closest('section');if(panel&&!document.getElementById('hrExportAllCsv')){const p=document.createElement('p');p.className='hr-export-actions';p.innerHTML='<button type="button" class="button secondary" id="hrExportAllCsv">Exportar todos CSV</button> <button type="button" class="button secondary" id="hrExportAllXlsx">Exportar todos Excel</button>';panel.append(p);for(const [id,kind] of [['hrExportAllCsv','csv'],['hrExportAllXlsx','xlsx']])p.querySelector('#'+id).onclick=()=>exportData(s.hrEmployees||[],kind).catch(e=>notify(e.message))}
document.querySelectorAll('[data-hr-person]').forEach(b=>{const e=(s.hrEmployees||[]).find(x=>x.id===b.dataset.hrPerson);if(!e)return;const btn=document.createElement('button');btn.className='button secondary';btn.type='button';btn.textContent='Ficha completa';btn.onclick=()=>edit(e);b.parentNode.insertBefore(btn,b);});
function edit(e){const d=document.createElement('dialog');d.className='hr-editor';d.innerHTML='<header class="hr-editor-header"><div><small>ENGEFEX · FUNCIONÁRIOS</small><h2>Ficha de '+esc(e.name)+'</h2></div><button type="button" class="hr-editor-close" data-close>×</button></header><form><div class="hr-editor-fields">'+F.map(([key,label])=>'<label class="hr-edit-field"><span>'+label+'</span>'+(key==='companyStatus'?'<select name="companyStatus">'+[['engefex','Engefex'],['outro_cnpj','Outro CNPJ'],['afastado','Afastado']].map(([v,t])=>'<option value="'+v+'" '+(e.companyStatus===v?'selected':'')+'>'+t+'</option>').join('')+'</select>':key==='active'?'<select name="active"><option value="true" '+(e.active!==false?'selected':'')+'>Ativo</option><option value="false" '+(e.active===false?'selected':'')+'>Inativo</option></select>':'<input name="'+key+'" type="'+(['birthDate','admissionDate'].includes(key)?'date':'text')+'" value="'+esc(e[key]||'')+'" '+(key==='name'?'required':'')+'>')+'</label>').join('')+'</div><footer class="hr-editor-footer"><button type="button" class="button secondary" data-csv>CSV</button><button type="button" class="button secondary" data-xlsx>Excel</button><button type="button" class="button secondary" data-cancel>Cancelar</button><button type="submit" class="button primary">Salvar alterações</button></footer></form>';document.body.append(d);const close=()=>{d.close();d.remove()};d.querySelector('[data-close]').onclick=d.querySelector('[data-cancel]').onclick=close;d.querySelector('[data-csv]').onclick=()=>exportData([e],'csv').catch(err=>notify(err.message));d.querySelector('[data-xlsx]').onclick=()=>exportData([e],'xlsx').catch(err=>notify(err.message));d.querySelector('form').onsubmit=async ev=>{ev.preventDefault();if(!root.EngefexAccess?.canWrite('hr-employees'))return notify('Sem permissão para editar.');const values=Object.fromEntries(new FormData(ev.currentTarget));const next=structuredClone(s),target=next.hrEmployees.find(x=>x.id===e.id);if(!target)return notify('Cadastro não encontrado');Object.assign(target,values,{active:values.active==='true',employmentStatus:values.active==='true'?'ativo':'inativo'});const save=d.querySelector('[type=submit]');save.disabled=true;try{const ok=await persist(next,'Ficha atualizada no Supabase');if(ok===false)throw Error('Servidor não confirmou salvamento');close();render()}catch(err){notify(err.message);save.disabled=false}};d.showModal();}
}
const prev=root.EngefexRH.attach;root.EngefexRH.attach=function(...args){prev(...args);attach(...args)};
})(window);